import datetime

def derive(record):
    derived = {}

    # Determine if the study is an applicable clinical trial based on the definitions
    derived['is_applicable_trial'] = False
    if record.get('protocolSection', {}).get('designModule', {}).get('studyType') == 'INTERVENTIONAL':
        if record.get('protocolSection', {}).get('oversightModule', {}).get('isFdaRegulatedDevice', False):
            derived['is_applicable_trial'] = True
        elif record.get('protocolSection', {}).get('oversightModule', {}).get('isFdaRegulatedDrug', False):
            derived['is_applicable_trial'] = True

    # Calculate the submission deadline
    primary_completion_date = record.get('protocolSection', {}).get('statusModule', {}).get('primaryCompletionDateStruct', {}).get('date')
    if primary_completion_date:
        try:
            pc_date = datetime.datetime.strptime(primary_completion_date, "%Y-%m-%d")
            derived['submission_deadline'] = (pc_date + datetime.timedelta(days=365)).strftime("%Y-%m-%d")
        except ValueError:
            derived['submission_deadline'] = None

    # Check if the study has results submitted
    derived['results_submitted_late'] = False
    if derived['is_applicable_trial']:
        results_first_submit_date = record.get('protocolSection', {}).get('statusModule', {}).get('resultsFirstSubmitDate')
        if results_first_submit_date and derived['submission_deadline']:
            try:
                rs_date = datetime.datetime.strptime(results_first_submit_date, "%Y-%m-%d")
                sd_date = datetime.datetime.strptime(derived['submission_deadline'], "%Y-%m-%d")
                derived['results_submitted_late'] = rs_date > sd_date
            except ValueError:
                derived['results_submitted_late'] = None

    return derived
